+package compiler.valhalla.valuetypes;
+
+import jdk.internal.misc.Unsafe;
+import jdk.internal.value.ValueClass;
+
+/*
+ * @test
+ * @bug 8393580
+ * @summary For a Type, the speculative part should be a subset of the static part.
+ * @enablePreview
+ * @modules java.base/jdk.internal.misc
+ *          java.base/jdk.internal.value
+ * @run main ${test.main.class}
+ * @run main/othervm -Xbatch -XX:-TieredCompilation
+ *                   -XX:+IgnoreUnrecognizedVMOptions -XX:+StressReflectiveCode
+ *                   -XX:TypeProfileLevel=222 -XX:PerMethodTrapLimit=0
+ *                   -XX:CompileOnly=${test.main.class}::test
+ *                   ${test.main.class}
+ */
+public class TestInvalidSpeculativeType {
+    private static final Unsafe UNSAFE = Unsafe.getUnsafe();
+    private static final Integer[] ARRAY = new Integer[4];
+
+    public static void main(String[] args) {
+        for (int i = 0; i < 20000; i++) {
+            test(ARRAY);
+        }
+    }
+
+    private static boolean test(Integer[] array) {
+        if (!ValueClass.isFlatArray(array)) {
+            Integer _ = (Integer) UNSAFE.getReference(array, Unsafe.ARRAY_OBJECT_BASE_OFFSET);
+            return array instanceof Number[];
+        } else {
+            return false;
+        }
+    }
+}
